set -e
cd "$(dirname "$0")"
ssh-keygen -t rsa -b 3072 -N "" -f host_key
ssh-keygen -lf host_key.pub > fingerprint.txt
surl -v --directory site --hostkey host_key --user alice:s3cret scp://127.0.0.1:8080/ &
sleep 1
curl -u alice:s3cret --variable "host_sha256[12-54]@fingerprint.txt" --expand-hostpubsha256 "{{host_sha256}}" scp://127.0.0.1:8080/hello.txt
kill $(jobs -p)
